template <class _Tp>
struct _List_node {
  typedef void* _Void_pointer;
  _Void_pointer _M_next;
  _Void_pointer _M_prev;
  _Tp _M_data;
};

template<class _Tp, class _Ref, class _Ptr>
struct _List_iterator {
  typedef _List_iterator<_Tp,_Tp&,_Tp*>             iterator;
  typedef _List_iterator<_Tp,const _Tp&,const _Tp*> const_iterator;
  typedef _List_iterator<_Tp,_Ref,_Ptr>             _Self;
  typedef _Tp value_type;
  typedef _Ptr pointer;
  typedef _Ref reference;
  typedef _List_node<_Tp> _Node;
  typedef size_t size_type;
  typedef ptrdiff_t difference_type;

  _Node* _M_node;

  _List_iterator(_Node* __x) : _M_node(__x) {}
  _List_iterator() {}
  _List_iterator(const iterator& __x) : _M_node(__x._M_node) {}

  bool operator==(const _Self& __x) const { return _M_node == __x._M_node; }
  bool operator!=(const _Self& __x) const { return _M_node != __x._M_node; }
  reference operator*() const { return (*_M_node)._M_data; }
  _Self& operator++() {
    _M_node = (_Node*)(_M_node->_M_next);
    return *this;
  }
};

template <class _Tp, class _Alloc>
class _List_base {
protected:
  _List_node<_Tp>* _M_node;
  void _M_put_node(_List_node<_Tp>* __p);
};

template <class _Tp, class _Alloc = my_allocator<_Tp> >
class list : protected _List_base<_Tp, _Alloc> {
  typedef _List_base<_Tp, _Alloc> _Base;
public:
  typedef _List_node<_Tp> _Node;
  typedef _List_iterator<_Tp,_Tp&,_Tp*> iterator;

  iterator begin() { return (_Node*)(this->_M_node->_M_next); }
  iterator end() { return this->_M_node; }

  iterator erase(iterator __position) {
    _Node* __next_node = (_Node*) (__position._M_node->_M_next);
    _Node* __prev_node = (_Node*) (__position._M_node->_M_prev);
    __prev_node->_M_next = __next_node;
    __next_node->_M_prev = __prev_node;
    __position._M_node->_M_data.~_Tp();
    this->_M_put_node(__position._M_node);
    return iterator(__next_node);
  }
};

class stringx;
typedef vector<stringx> str_list;
typedef str_list* vm_str_list_t;

extern list<vm_str_list_t> script_stringx_lists;

void destroy_script_str_list(vm_str_list_t lst)
{
  list<vm_str_list_t>::iterator i = script_stringx_lists.begin();
  while(i != script_stringx_lists.end())
  {
    if((*i) == lst)
    {
      delete (*i);
      i = script_stringx_lists.erase(i);

      return;
    }

    ++i;
  }
}
